import { api } from "../client";
import type {
  PaymentIntentRequest,
  PaymentIntentResponse,
  Payment,
  ApiResponse,
} from "../types";

export const paymentsService = {
  async createPaymentIntent(
    data: PaymentIntentRequest
  ): Promise<ApiResponse<PaymentIntentResponse>> {
    return api.post<ApiResponse<PaymentIntentResponse>>(
      "/payments/create-payment-intent",
      data
    );
  },

  async getPaymentStatus(applicationId: string): Promise<ApiResponse<Payment>> {
    return api.get<ApiResponse<Payment>>(
      `/payments/application/${applicationId}`
    );
  },
};
