import { api } from "../client";
import type {
  Application,
  CreateApplicationRequest,
  SaveDraftRequest,
  ApiResponse,
  PaginatedResponse,
  ApplicationStatus,
} from "../types";

export const applicationsService = {
  async create(
    data: Partial<CreateApplicationRequest>
  ): Promise<ApiResponse<Application>> {
    return api.post<ApiResponse<Application>>("/applications", data);
  },

  async getAll(params?: {
    page?: number;
    limit?: number;
    status?: ApplicationStatus;
  }): Promise<ApiResponse<PaginatedResponse<Application>>> {
    return api.get<ApiResponse<PaginatedResponse<Application>>>(
      "/applications",
      {
        params,
      }
    );
  },

  async getMyApplications(params?: {
    page?: number;
    limit?: number;
    status?: ApplicationStatus;
  }): Promise<ApiResponse<PaginatedResponse<Application>>> {
    return api.get<ApiResponse<PaginatedResponse<Application>>>(
      "/applications/my",
      {
        params,
      }
    );
  },

  async getById(id: string): Promise<ApiResponse<Application>> {
    return api.get<ApiResponse<Application>>(`/applications/${id}`);
  },

  async update(
    id: string,
    data: Partial<CreateApplicationRequest>
  ): Promise<ApiResponse<Application>> {
    return api.put<ApiResponse<Application>>(`/applications/${id}`, data);
  },

  async saveDraft(
    id: string,
    data: SaveDraftRequest
  ): Promise<ApiResponse<{ message: string; applicationId: string }>> {
    return api.post<ApiResponse<{ message: string; applicationId: string }>>(
      `/applications/${id}/draft`,
      data
    );
  },

  async submit(
    id: string
  ): Promise<ApiResponse<{ message: string; applicationNumber: string }>> {
    return api.post<
      ApiResponse<{ message: string; applicationNumber: string }>
    >(`/applications/${id}/submit`);
  },

  async updateStatus(
    id: string,
    status: ApplicationStatus,
    adminNotes?: string
  ): Promise<ApiResponse<Application>> {
    return api.patch<ApiResponse<Application>>(`/applications/${id}/status`, {
      status,
      adminNotes,
    });
  },

  async delete(id: string): Promise<ApiResponse<{ message: string }>> {
    return api.delete<ApiResponse<{ message: string }>>(`/applications/${id}`);
  },

  async saveTravelers(
    id: string,
    travelers: any[]
  ): Promise<ApiResponse<Application>> {
    return api.post<ApiResponse<Application>>(
      `/applications/${id}/travelers`,
      travelers
    );
  },
};
